const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));

const mk=a=>{const cs=a.length<=2;let e=(cs?a.toUpperCase():a).replace(/[.*+?^${}()|[\]\\]/g,"\\$&").replace(/\s+/g,"[\\s-]+");return new RegExp("(?<![A-Za-z0-9+#])"+e+"(?![A-Za-z0-9+#])",cs?"":"i")};
const SK=[["Python"],["Java"],["C++",["cpp"]],["C",["c programming","c language"]],["JavaScript",["js","ecmascript"]],["TypeScript"],["HTML",["html5"]],["CSS",["css3"]],["React",["reactjs","react.js"]],["Node.js",["nodejs"]],["SQL"],["MySQL"],["PostgreSQL",["postgres"]],["MongoDB",["mongo"]],["Git"],["GitHub"],["Linux"],["Docker"],["Data Structures",["dsa"]],["Algorithms",["algorithm"]],["OOP",["oops","object oriented programming","object-oriented"]],["DBMS",["database management"]],["Operating Systems",["operating system"]],["Computer Networks",["networking","computer networking"]],["Cybersecurity",["cyber security","information security","infosec"]],["Cryptography",["encryption"]],["AI",["artificial intelligence"]],["Machine Learning",["ml"]],["Problem Solving",["problem-solving"]]].map(([n,a=[]])=>({n,res:[n,...a].map(mk)}));
const find=t=>SK.filter(s=>s.res.some(r=>r.test(t))).map(s=>s.n);
const WEAK=[[/\bmade\b/gi,"Developed / Built / Designed","“Made” is vague about what you actually did."],[/\bworked on\b/gi,"Contributed to / Developed","“Worked on” hides your specific role."],[/\bhelped( to)?\b/gi,"Contributed to / Supported","“Helped” understates ownership; say what you contributed."],[/\bdid\b/gi,"Completed / Implemented","“Did” says nothing about the task."],[/\bresponsible for\b/gi,"Managed / Handled (only if accurate)","Describes duty, not action or result."],[/\bused\b/gi,"Implemented / Integrated / Applied","“Used” is passive; show how the tool was applied."],[/\bgood knowledge of\b/gi,"Applied / Proficient in (only if accurate)","Self-assessment without evidence; show it in a project."]];
const ING={build:"building",develop:"developing",design:"designing",create:"creating",implement:"implementing",test:"testing",debug:"debugging"};
const STARTS=[[/^helped( to)?\s+(build|develop|design|create|implement|test|debug)\b/i,null],[/^(made|created)\s+/i,"Developed "],[/^worked on\s+/i,"Contributed to "],[/^helped( to)?\s+/i,"Contributed to "],[/^did\s+/i,"Completed "],[/^responsible for\s+/i,"Handled "],[/^used\s+/i,"Applied "]];
function skillEvidence(text,name){const skill=SK.find(x=>x.n===name);if(!skill)return null;for(const re of skill.res){const m=re.exec(String(text));if(m){const start=String(text).lastIndexOf("\n",m.index),end=String(text).indexOf("\n",m.index);return String(text).slice(Math.max(0,start+1),end<0?String(text).length:end).trim().slice(0,240)}}return null}
function assessExtraction(text){const value=String(text||""),chars=value.replace(/\s/g,"").length,lines=value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),heads=lines.filter(x=>/^(education|academics?|skills?|technical skills|experience|work experience|projects?|certifications?|summary|objective|profile)$/i.test(x.replace(/[:\s]+$/,""))).length,bullets=lines.filter(x=>/^[-•*▪●◦·]\s*\S/.test(x)).length;let confidence=0;confidence+=chars>=500?45:chars>=250?35:chars>=120?25:chars>=50?12:chars>0?4:0;confidence+=lines.length>=12?20:lines.length>=6?14:lines.length>=3?7:0;confidence+=heads>=4?25:heads>=2?17:heads?9:0;confidence+=bullets>=3?10:bullets?5:0;confidence=Math.min(100,confidence);const warnings=[];if(chars<30)warnings.push("Very little text was extracted. This PDF may be scanned or image-only; OCR is needed before analysis.");else if(chars<120)warnings.push("Only a small amount of text was found. Check the preview for missing sections.");if(lines.length<4)warnings.push("Few text lines were detected; layout extraction may be incomplete.");if(heads<2&&chars>=120)warnings.push("Resume section headings were not clearly detected.");return{characters:chars,lines:lines.length,sections:heads,confidence,reliable:chars>=120&&lines.length>=4&&confidence>=40,warnings}}
function weakAdvice(phrase){if(/^helped/i.test(phrase))return"Keep the shared contribution clear. Specify the part you personally completed; choose a stronger verb only if accurate.";if(/^worked on/i.test(phrase))return"Name your specific task. Consider ‘tested’, ‘documented’, or ‘implemented’ only if that is what you did.";if(/^made/i.test(phrase))return"‘Built’ can be clearer for a thing you assembled; use it only if it preserves your role.";if(/^used/i.test(phrase))return"Describe how you applied the tool. Avoid ‘integrated’ or ‘implemented’ unless you did that work.";if(/^responsible/i.test(phrase))return"State the actions you actually performed; do not turn responsibility into ownership without evidence.";return"Replace this vague wording with the specific action you performed, without adding claims."}function improve(raw){const before=String(raw).replace(/^\s*[-•*▪●◦·]\s*/,"").trim();let after=before;const notes=[];if(/^made\s+/i.test(after))after=after.replace(/^made\s+/i,"Built ");else after=after.charAt(0).toUpperCase()+after.slice(1);if(!/[.!?]$/.test(after))after+=".";if(/^helped\b/i.test(before))notes.push("This wording describes shared work. Keep it, and specify your own contribution only when you can verify it.");else if(/^worked on\b/i.test(before))notes.push("Describe the specific task you performed; no ownership verb was inferred.");else if(/^used\b/i.test(before))notes.push("Keep ‘used’ unless a more specific action accurately describes your work.");if(!find(before).length)notes.push("No recognized technology appears in this bullet. Add tools only if you actually used them.");if(!/\b(to|for|so that|which|that|enabling|allowing|because)\b/i.test(before))notes.push("Purpose or outcome is not stated. Add one only if you can support it.");return{before,after,notes}}function structure(t){const L=t.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),out=[],add=(sev,title,why,fix)=>out.push({sev,title,why,fix});
if(!/[\w.+-]+@[\w-]+\.[\w.-]+/.test(t))add("high","No email address found","Recruiters need a way to contact you.","Add a professional email near the top.");
if(!/(\+?\d[\d\s-]{8,}\d)/.test(t))add("medium","No phone number found","A phone number helps recruiters reach you quickly.","Add a phone number in the header.");
const H={Education:/^(education|academics?|academic background|qualifications?)$/i,Skills:/^(technical )?skills?( summary)?$/i,Projects:/^(academic |personal )?projects?$/i,Experience:/^(work |professional )?(experience|internships?)$/i,Certifications:/^certifications?( & courses)?$/i,Achievements:/^(achievements?|awards?|honou?rs)$/i};
const heads=L.filter(x=>x.length<40&&Object.values(H).some(r=>r.test(x.replace(/[:\s]+$/,""))));
const has=k=>heads.some(x=>H[k].test(x.replace(/[:\s]+$/,"")));
[["Education","high"],["Skills","high"],["Projects","medium"]].forEach(([k,s])=>{if(!has(k))add(s,k+" section not detected","This section is expected on most technical resumes.","Add a clearly titled “"+k+"” heading.")});
[["Experience","Optional for freshers. Add internships or volunteering if you have them."],["Certifications","Optional. Add relevant courses or certificates if you have them."],["Achievements","Optional. Add hackathons, awards or competitions if applicable."]].forEach(([k,m])=>{if(!has(k))add("info",k+" section not found",m,"No action required if it doesn’t apply to you.")});
if(heads.some(x=>x===x.toUpperCase())&&heads.some(x=>x!==x.toUpperCase()))add("low","Inconsistent heading style","Some headings are ALL CAPS and others are not.","Use one heading style throughout.");
const long=L.filter(x=>x.length>220);if(long.length)add("medium",long.length+" very long line(s)","Lines over 220 characters are hard to scan.","Split into shorter bullets (1–2 lines each).");
const seen={},rep=[];L.forEach(x=>{const k=x.toLowerCase();if(k.length>25){seen[k]=(seen[k]||0)+1;if(seen[k]==2)rep.push(x)}});if(rep.length)add("low","Repeated content","These lines appear more than once: “"+rep.slice(0,2).join("”, “").slice(0,140)+"”","Remove the duplicates.");
const lc=L.filter(x=>/^[-•*▪●◦·]\s*[a-z]/.test(x)).length;if(lc)add("low",lc+" bullet(s) start with a lowercase letter","Inconsistent capitalization looks unpolished.","Start every bullet with a capital letter.");
if(t.trim().length<300)add("high","Very little text extracted","Under 300 characters were found. The file may be incomplete or image-based.","Paste the resume text directly or use a text-based PDF.");
if(L.length<8&&t.length>600||L.some(x=>x.length>600))add("medium","Possible text extraction problem","Text appears merged into very few lines, so section detection may be unreliable.","Paste the text with line breaks, or re-export the PDF.");
if(/\uFFFD/.test(t))add("medium","Unreadable characters found","Some characters could not be decoded.","Re-export the file or paste plain text.");
add("info","Visual layout not inspected","CVPILOT reads text only. It cannot check fonts, margins, columns or alignment.","Review the visual layout yourself before sending.");
return out}
function analyze(resume,jd,options={}){const req=find(jd),evidence=Object.fromEntries(req.map(k=>[k,skillEvidence(resume,k)])),matched=req.filter(k=>evidence[k]),absent=req.filter(k=>!evidence[k]),unreliable=options.extractionReliable===false,missing=unreliable?[]:absent,undetected=unreliable?absent:[],score=unreliable?null:(req.length?Math.round(matched.length/req.length*100):0);const weak=WEAK.map(([r,s,why])=>({phrase:r.source.replace(/\\b|\( to\)\?/g,"").replace(/\\b/g,""),s:weakAdvice(r.source.includes("helped")?"helped":r.source.includes("worked on")?"worked on":r.source.includes("responsible")?"responsible for":r.source.replace(/\\b|\\/g,"")),why,n:(resume.match(r)||[]).length})).filter(w=>w.n);const lines=resume.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const bl=lines.filter(l=>/^[-•*▪●◦·]\s*\S/.test(l)||/^made\s+/i.test(l)).slice(0,10).map(improve).filter(b=>b.after.replace(/[.!?]$/g,"")!==b.before||b.notes.length);const st=structure(resume),rec=[];if(missing.length)rec.push("These skills were not mentioned in the extracted resume text; this does not mean you lack them: "+missing.join(", ")+".");if(undetected.length)rec.push("Extraction confidence is low. Skill gaps are not scored until the resume text is reviewed.");st.filter(x=>x.sev=="high").forEach(x=>rec.push(x.title+". "+x.fix));if(weak.length)rec.push("Review vague phrases and describe your specific contribution accurately.");if(bl.length)rec.push("Review "+bl.length+" project bullet suggestion(s); accept only wording that preserves your meaning.");st.filter(x=>x.sev=="medium").forEach(x=>rec.push(x.title+". "+x.fix));if(!rec.length)rec.push("Looks solid. Do a final read-through for accuracy.");return{req,matched,missing,undetected,evidence,score,weak,bl,st,rec,resume,extractionConfidence:Number.isFinite(options.extractionConfidence)?options.extractionConfidence:null,extractionReliable:!unreliable}}const report=r=>["CVPILOT ANALYSIS REPORT","Keyword overlap score: "+(r.score==null?"unavailable":r.score+"%")+" ("+r.matched.length+" of "+r.req.length+" identified skills). This measures keyword overlap only, not ATS selection.","","MATCHED: "+(r.matched.join(", ")||"none"),"NOT MENTIONED: "+(r.missing.join(", ")||"none")+"\nUNDETECTED: "+(r.undetected.join(", ")||"none"),"","WEAK PHRASES:",...r.weak.map(w=>"- “"+w.phrase+"” x"+w.n+" → "+w.s),"","BULLET SUGGESTIONS:",...r.bl.map(b=>"- Before: "+b.before+"\n  After: "+b.after),"","STRUCTURE:",...r.st.map(x=>"- ["+x.sev.toUpperCase()+"] "+x.title+": "+x.fix),"","RECOMMENDATIONS:",...r.rec.map((x,i)=>(i+1)+". "+x)].join("\n");
if(typeof module!=='undefined')module.exports={find,skillEvidence,assessExtraction,analyze,improve,structure,report,WEAK,SK};

